import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# packet.DeathInfo{Cause: "fall", Messages: []string{"death.fell.accident.generic", "Steve"}}
FALL = bytes.fromhex("0466616c6c021b64656174682e66656c6c2e6163636964656e742e67656e65726963055374657665")

# generated by gophertunnel b8bd735:
# packet.DeathInfo{}
EMPTY = bytes.fromhex("0000")

GOLDENS = [
    pytest.param(
        v2225.DeathInfoPacket(
            death_cause_attack_name="fall",
            death_cause_message_list=["death.fell.accident.generic", "Steve"],
        ),
        FALL,
        id="fall",
    ),
    pytest.param(v2225.DeathInfoPacket(), EMPTY, id="empty"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_death_info_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_death_info_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
